ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"status": 500,
	"code": "PROMOTIONS_MOBILE",
	"message": {
	  "message": vars.errorMessageOutput default p('sisext-sapi.promotions.errorMessage')
	},
	"messageServer": "",
	"cause": [
	  {
	    "origin": app.name,
	    "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
	  }
	]
}

%dw 2.0
output application/json
---
{
	"status": 400,
	"code": "BAD_REQUEST",
	"message": {
	  "message": "validations is required when analytics=true"
	},
	"messageServer": "",
	"cause": [
	  {
	    "origin": app.name,
	    "message": "Missing validations object for analytics path"
	  }
	]
}

%dw 2.0
output application/json
var base = vars.inputPayload default {}
var body = base -- ["type", "analytics", "validations"]
var fromRequest = body.predefinedPromotions default []
var fromAnalytics = vars.analyticsIds default []
---
(body - "predefinedPromotions") ++ {
	predefinedPromotions: (fromRequest ++ fromAnalytics) distinctBy $
}

%dw 2.0
output application/json
---
{
	"status": 500,
	"code": "PROMOTIONS_FIXED",
	"message": {
	  "message": vars.errorMessageOutput default p('sisext-sapi.promotions.errorMessage')
	},
	"messageServer": "",
	"cause": [
	  {
	    "origin": app.name,
	    "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
	  }
	]
}

%dw 2.0
output application/json
---
{
	"status": 400,
	"code": "BAD_REQUEST",
	"message": {
	  "message": "Invalid type. Allowed values: movil, fijo, mobile, fixed"
	},
	"messageServer": "",
	"cause": [
	  {
	    "origin": app.name,
	    "message": "Invalid promotions type: " ++ (vars.promotionType default "")
	  }
	]
}

%dw 2.0
output application/json
var v = vars.inputPayload.validations default {}
var cobDesName = p('analitica-sapi.solicitud.cobDes.nombre')
var cobDesValue = p('analitica-sapi.solicitud.cobDes.valor')
var coberturaName = p('analitica-sapi.solicitud.cobertura.nombre')
fun param(nombre, valor) = {
	Nombre: nombre,
	Valor: valor,
	Detalle: null
}
---
{
	SolicitudOfertaSugerida: [
		{
			Nombre: cobDesName,
			Valor: cobDesValue,
			Detalle: [
				{
					Nombre: coberturaName,
					Valor: v.technology,
					Detalle: [
						param("CodigoMunicipio", v.municipalityCode),
						param("CodigoDepartamento", v.departmentCode),
						param("Latitud", v.latitude),
						param("Longitud", v.longitude),
						param("CodigoLote", v.lotCode default ""),
						param("Distrito", v.district default ""),
						param("Localidad", v.locality),
						param("Estrato", v.stratum default ""),
						param("Direccion_GIS", v.gisAddress default ""),
						param("Molecula", v.molecule default ""),
						param("Proposito", v.purpose default ""),
						param("Tecnologia", v.technology)
					]
				}
			]
		},
		param("SistemaOrigen", v.originSystem),
		param("ClienteUen", v.clientUen),
		param("SegmentoUEN", v.uenSegment),
		param("TipoIdentificacion", v.documentType),
		param("NumeroIdentificacion", v.documentNumber),
		param("TipoTramite", v.procedureType),
		param("NumAgrupacion", v.groupingNumber),
		param("CodigoAlianza", v.allianceCode)
	]
}
